package dev.ide.core.discovery

import java.net.URI

/**
 * Multi-tier screenshot and visual asset extraction pipeline for GitHub repositories.
 * Configured with selectable tiers of aggressiveness.
 */
object ScreenshotExtractor {

    enum class AggressivenessTier(val level: Int, val description: String) {
        /** Tier 0: Guaranteed instant OpenGraph card generated by GitHub (1200x630). Zero rate-limit cost. */
        TIER_0_OPENGRAPH(0, "Fast OpenGraph Social Card"),

        /** Tier 1: Fastlane and Play Store metadata paths (official store screenshots). */
        TIER_1_STORE_METADATA(1, "Fastlane & Play Store Metadata"),

        /** Tier 2: Intelligent README Markdown and HTML scraping with heuristic scoring. */
        TIER_2_README_SCRAPE(2, "Intelligent README Image Scraping"),

        /** Tier 3: Repository asset directories crawler (/screenshots, /art, /assets). */
        TIER_3_ASSET_CRAWLER(3, "Repository Assets Directory Scan"),

        /** Tier 4: Static AST and layout inspection (detects @Preview composables and launcher graphics). */
        TIER_4_AST_PREVIEWS(4, "Static AST @Preview Target Analysis"),

        /** Tier 5: Headless On-Device Build and Offscreen Snapshot (Staged contract for Vivari/ART). */
        TIER_5_ACTIVE_HEADLESS_RENDER(5, "Headless On-Device Build & Render")
    }

    data class ScreenshotCandidate(
        val url: String,
        val tier: AggressivenessTier,
        val confidenceScore: Double,
        val caption: String? = null,
        val isHeroBanner: Boolean = false
    )

    private val BADGE_DOMAINS = listOf(
        "shields.io",
        "badge.svg",
        "travis-ci",
        "codecov.io",
        "workflow/badge",
        "github.com/workflows",
        "actions/workflows",
        "matrix.to",
        "discord.gg",
        "sponsors",
        "repology.org",
        "contrib.rocks",
        "weblate.org"
    )

    private val SCREENSHOT_KEYWORDS = listOf(
        "screenshot",
        "preview",
        "demo",
        "mockup",
        "ui",
        "device",
        "phone",
        "mobile",
        "screen",
        "phonescreenshot",
        "showcase"
    )

    /**
     * Resolves the best visual preview for a repository given an aggressiveness tier.
     * Guaranteed never to return empty: falls back to Tier 0 OpenGraph card if higher tiers yield no matches.
     */
    fun resolveScreenshots(
        owner: String,
        repo: String,
        readmeContent: String? = null,
        fileTreePaths: List<String> = emptyList(),
        branch: String = "HEAD",
        maxTier: AggressivenessTier = AggressivenessTier.TIER_2_README_SCRAPE
    ): List<ScreenshotCandidate> {
        val candidates = mutableListOf<ScreenshotCandidate>()

        // Tier 1: Check Fastlane / Play store directory patterns
        if (maxTier.level >= AggressivenessTier.TIER_1_STORE_METADATA.level && fileTreePaths.isNotEmpty()) {
            val storeScreenshots = extractStoreMetadataScreenshots(owner, repo, branch, fileTreePaths)
            candidates.addAll(storeScreenshots)
        }

        // Tier 2: Scrape README content
        if (maxTier.level >= AggressivenessTier.TIER_2_README_SCRAPE.level && !readmeContent.isNullOrBlank()) {
            val readmeScreenshots = extractReadmeScreenshots(owner, repo, branch, readmeContent)
            candidates.addAll(readmeScreenshots)
        }

        // Tier 3: Scan asset directories
        if (maxTier.level >= AggressivenessTier.TIER_3_ASSET_CRAWLER.level && fileTreePaths.isNotEmpty()) {
            val assetScreenshots = extractAssetDirectoryScreenshots(owner, repo, branch, fileTreePaths)
            candidates.addAll(assetScreenshots)
        }

        // Tier 4: AST / Compose Preview metadata cues
        if (maxTier.level >= AggressivenessTier.TIER_4_AST_PREVIEWS.level && fileTreePaths.isNotEmpty()) {
            val astCandidates = extractAstPreviewCandidates(owner, repo, branch, fileTreePaths)
            candidates.addAll(astCandidates)
        }

        // Sort by confidence score descending
        val sorted = candidates.sortedByDescending { it.confidenceScore }

        // Always guarantee at least the Tier 0 OpenGraph card
        val openGraphFallback = ScreenshotCandidate(
            url = openGraphCardUrl(owner, repo),
            tier = AggressivenessTier.TIER_0_OPENGRAPH,
            confidenceScore = 0.5,
            caption = "$owner/$repo GitHub Overview Card",
            isHeroBanner = true
        )

        return if (sorted.isNotEmpty()) sorted else listOf(openGraphFallback)
    }

    /**
     * Generates GitHub's official 1200x630 OpenGraph card URL for a repository.
     */
    fun openGraphCardUrl(owner: String, repo: String): String {
        return "https://opengraph.githubassets.com/1/$owner/$repo"
    }

    /**
     * Extracts images from README markdown and HTML tags, filtering out build badges and small icons.
     */
    fun extractReadmeScreenshots(
        owner: String,
        repo: String,
        branch: String,
        readmeContent: String
    ): List<ScreenshotCandidate> {
        val candidates = mutableListOf<ScreenshotCandidate>()

        // 1. Match HTML <img ... src="..." ...>
        val htmlImgRegex = Regex("""<img\s+[^>]*?src=["']([^"']+)["'][^>]*?>""", RegexOption.IGNORE_CASE)
        for (match in htmlImgRegex.findAll(readmeContent)) {
            val rawSrc = match.groupValues[1]
            val fullTag = match.value
            processImageCandidate(rawSrc, fullTag, owner, repo, branch, AggressivenessTier.TIER_2_README_SCRAPE)?.let {
                candidates.add(it)
            }
        }

        // 2. Match Markdown ![alt](url)
        val mdImgRegex = Regex("""!\[(.*?)\]\(([^)]+)\)""")
        for (match in mdImgRegex.findAll(readmeContent)) {
            val alt = match.groupValues[1]
            val rawSrc = match.groupValues[2].trim().split(" ")[0] // Handle optional markdown title
            processImageCandidate(rawSrc, alt, owner, repo, branch, AggressivenessTier.TIER_2_README_SCRAPE)?.let {
                candidates.add(it)
            }
        }

        return candidates
    }

    /**
     * Extracts screenshots from standard Android Fastlane / Play store directory conventions.
     */
    private fun extractStoreMetadataScreenshots(
        owner: String,
        repo: String,
        branch: String,
        paths: List<String>
    ): List<ScreenshotCandidate> {
        val storePathPattern = Regex("""(fastlane/metadata|play/listings|metadata)/.*?/phoneScreenshots/.*\.(png|jpg|webp)$""", RegexOption.IGNORE_CASE)
        return paths.filter { storePathPattern.containsMatchIn(it) }.map { relPath ->
            val resolvedUrl = normalizeRawUrl(owner, repo, branch, relPath)
            ScreenshotCandidate(
                url = resolvedUrl,
                tier = AggressivenessTier.TIER_1_STORE_METADATA,
                confidenceScore = 0.95,
                caption = "Play Store Screenshot: ${relPath.substringAfterLast('/')}"
            )
        }
    }

    /**
     * Scans repository file paths for common screenshot directories.
     */
    private fun extractAssetDirectoryScreenshots(
        owner: String,
        repo: String,
        branch: String,
        paths: List<String>
    ): List<ScreenshotCandidate> {
        val assetDirPattern = Regex("""^(screenshots?|art|assets/screenshots?|docs/images?)/.*\.(png|jpg|webp)$""", RegexOption.IGNORE_CASE)
        return paths.filter { assetDirPattern.containsMatchIn(it) }.map { relPath ->
            val resolvedUrl = normalizeRawUrl(owner, repo, branch, relPath)
            ScreenshotCandidate(
                url = resolvedUrl,
                tier = AggressivenessTier.TIER_3_ASSET_CRAWLER,
                confidenceScore = 0.85,
                caption = "Repository Asset: ${relPath.substringAfterLast('/')}"
            )
        }
    }

    /**
     * Identifies layout XML and launcher graphics for AST analysis.
     */
    private fun extractAstPreviewCandidates(
        owner: String,
        repo: String,
        branch: String,
        paths: List<String>
    ): List<ScreenshotCandidate> {
        val launcherPattern = Regex("""mipmap-(xxxhdpi|xxhdpi|xhdpi)/ic_launcher\.(png|webp)$""", RegexOption.IGNORE_CASE)
        return paths.filter { launcherPattern.containsMatchIn(it) }.take(1).map { relPath ->
            val resolvedUrl = normalizeRawUrl(owner, repo, branch, relPath)
            ScreenshotCandidate(
                url = resolvedUrl,
                tier = AggressivenessTier.TIER_4_AST_PREVIEWS,
                confidenceScore = 0.70,
                caption = "High-Res App Icon"
            )
        }
    }

    private fun processImageCandidate(
        rawSrc: String,
        contextText: String,
        owner: String,
        repo: String,
        branch: String,
        tier: AggressivenessTier
    ): ScreenshotCandidate? {
        val cleanSrc = rawSrc.trim()
        if (cleanSrc.isBlank()) return null

        // Filter out known badge and counter domains
        val lower = cleanSrc.lowercase()
        if (BADGE_DOMAINS.any { lower.contains(it) }) return null

        // SVGs in READMEs are almost always small status icons or badges
        if (lower.endsWith(".svg") && !lower.contains("diagram") && !lower.contains("architecture")) {
            return null
        }

        // Calculate confidence score based on keywords and dimensions
        var score = 0.60
        val combinedContext = "$cleanSrc $contextText".lowercase()
        if (SCREENSHOT_KEYWORDS.any { combinedContext.contains(it) }) {
            score += 0.25
        }
        if (cleanSrc.contains("fastlane") || cleanSrc.contains("phoneScreenshots")) {
            score += 0.30
        }
        if (combinedContext.contains("width") || combinedContext.contains("height")) {
            score += 0.10
        }

        val resolvedUrl = normalizeRawUrl(owner, repo, branch, cleanSrc)
        return ScreenshotCandidate(
            url = resolvedUrl,
            tier = tier,
            confidenceScore = score.coerceIn(0.0, 1.0),
            caption = contextText.take(60),
            isHeroBanner = score >= 0.85
        )
    }

    /**
     * Resolves relative markdown paths (e.g. "docs/screenshot.png" or "./art/demo.jpg")
     * into absolute raw GitHub content URLs.
     */
    fun normalizeRawUrl(owner: String, repo: String, branch: String, path: String): String {
        if (path.startsWith("http://") || path.startsWith("https://")) {
            return path
        }
        val cleanPath = path.removePrefix("./").removePrefix("/")
        return "https://raw.githubusercontent.com/$owner/$repo/$branch/$cleanPath"
    }
}
